import Foundation
enum AppFormat { static let currency: NumberFormatter = { let f = NumberFormatter(); f.numberStyle = .currency; f.currencyCode = "CNY"; f.locale = Locale(identifier: "zh_CN"); f.minimumFractionDigits = 2; f.maximumFractionDigits = 2; return f }(); static func money(_ value: Decimal, currency: String = "CNY") -> String { let f = currency == "CNY" ? currency : currency; let n = NSDecimalNumber(decimal: value); return (f == "CNY" ? "¥" : f + " ") + (currency == "CNY" ? currencyString(n) : n.stringValue) }; private static func currencyString(_ n: NSDecimalNumber) -> String { currency.string(from: n) ?? n.stringValue }; static let month: Date.FormatStyle = .dateTime.year().month(.wide); static let day: Date.FormatStyle = .dateTime.month(.defaultDigits).day(.defaultDigits); static let time: Date.FormatStyle = .dateTime.hour().minute() }
